style.css:
@-moz-document domain("chat.openai.com") {
body, #__next {
    background-image: url("https://i.imgur.com/HVYFCsz.jpeg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    background-attachment: fixed;
    background-color: transparent;
  }

  .flex.h-full.flex-1.flex-col, .w-full.h-full.flex.flex-col {
    background: transparent !important; /* Remover fundos sólidos */
  }

  .dark .bg-black, .bg-white, .dark\:bg-gray-900 {
    background: transparent !important; /* Deixar toda a área do chat transparente */
  }
}
